// ==UserScript==
// @name         Valorant Minimap
// @namespace    https://github.com/Stiztz/tampermonkey-scripts-gg
// @version      2.1.0
// @description  minimap
// @match        https://*.bet365.com/*
// @include      /^https?:\/\/[^/]*\bbet365\.[a-z.]+\//
// @run-at       document-start
// @grant        none
// @icon         https://www.google.com/s2/favicons?domain=valorantesports.com
// @updateURL    https://raw.githubusercontent.com/Stiztz/tampermonkey-scripts-gg/main/minimap-valo.user.js
// @downloadURL  https://raw.githubusercontent.com/Stiztz/tampermonkey-scripts-gg/main/minimap-valo.user.js
// ==/UserScript==

/* ============================================================================================
   STANDALONE, separate from the HUD script: no shared in-memory state, no touching its config or panel.
   The ONLY thing shared (deliberately) is two localStorage keys, read and written by both, so labels
   you already taught one script don't have to be taught again:
       _pv_am_v  ->  IG (bet365 agent id)  ->  agent name
       _pv_wm_v  ->  IC (weapon icon id)   ->  weapon name
   Own config:  _vmm_cfg_v1        learned S4->IC:  _vmm_s4ic_v1
   ============================================================================================ */

(function () {
  'use strict';

  // ---- single instance guard ----
  // @match covers every frame, and bet365's SPA spawns iframes as you navigate. Without this
  // each one booted a whole copy: its own WebSocket hook, its own parser, its own paint loop.
  // They pile up the longer the tab is open, which is exactly what a gradual freeze looks like.
  try { if (window.top !== window.self) return; } catch (e) { return; }   // cross-origin frame: not ours either
  if (window.__vmmLoaded) { console.warn('[vm] already loaded in this page - second injection ignored'); return; }
  window.__vmmLoaded = true;
  // ====================== ASSETS (extraídos de tu script bet365: 12 minimapas oficiales, 29 retratos de agente, 20 iconos de arma Riot) ======================
  const AGENT_ICON_SET = new Set(['astra', 'breach', 'brimstone', 'chamber', 'clove', 'cypher', 'deadlock', 'fade', 'gekko', 'harbor', 'iso', 'jett', 'kayo', 'killjoy', 'miks', 'neon', 'omen', 'phoenix', 'raze', 'reyna', 'sage', 'skye', 'sova', 'tejo', 'veto', 'viper', 'vyse', 'waylay', 'yoru']);
  const WEAPON_ICON_SET = new Set(['ares', 'bandit', 'bucky', 'bulldog', 'classic', 'frenzy', 'ghost', 'guardian', 'judge', 'marshal', 'melee', 'odin', 'operator', 'outlaw', 'phantom', 'sheriff', 'shorty', 'spectre', 'stinger', 'vandal']);
  const MAP_LAYOUTS = {ascent:"data:image/jpeg;base64,",bind:"data:image/jpeg;base64,",haven:"data:image/jpeg;base64,",split:"data:image/jpeg;base64,",icebox:"data:image/jpeg;base64,",breeze:"data:image/jpeg;base64,",fracture:"data:image/jpeg;base64,",pearl:"data:image/jpeg;base64,",lotus:"data:image/jpeg;base64,",sunset:"data:image/jpeg;base64,",abyss:"data:image/jpeg;base64,",corrode:"data:image/jpeg;base64,"};
  const AGENT_ICON_CSS = `
.a-gekko{background-image:url("data:image/png;base64,")}
.a-fade{background-image:url("data:image/png;base64,")}
.a-breach{background-image:url("data:image/png;base64,")}
.a-deadlock{background-image:url("data:image/png;base64,")}
.a-tejo{background-image:url("data:image/png;base64,")}
.a-raze{background-image:url("data:image/png;base64,")}
.a-chamber{background-image:url("data:image/png;base64,")}
.a-kayo{background-image:url("data:image/png;base64,")}
.a-skye{background-image:url("data:image/png;base64,")}
.a-cypher{background-image:url("data:image/png;base64,")}
.a-sova{background-image:url("data:image/png;base64,")}
.a-miks{background-image:url("data:image/png;base64,")}
.a-killjoy{background-image:url("data:image/png;base64,")}
.a-harbor{background-image:url("data:image/png;base64,")}
.a-vyse{background-image:url("data:image/png;base64,")}
.a-viper{background-image:url("data:image/png;base64,")}
.a-phoenix{background-image:url("data:image/png;base64,")}
.a-veto{background-image:url("data:image/png;base64,")}
.a-astra{background-image:url("data:image/png;base64,")}
.a-brimstone{background-image:url("data:image/png;base64,")}
.a-iso{background-image:url("data:image/png;base64,")}
.a-clove{background-image:url("data:image/png;base64,")}
.a-neon{background-image:url("data:image/png;base64,")}
.a-yoru{background-image:url("data:image/png;base64,")}
.a-waylay{background-image:url("data:image/png;base64,")}
.a-sage{background-image:url("data:image/png;base64,")}
.a-reyna{background-image:url("data:image/png;base64,")}
.a-omen{background-image:url("data:image/png;base64,")}
.a-jett{background-image:url("data:image/png;base64,")}
`;
  const WEAPON_ICON_CSS = `
.w-odin{aspect-ratio:384/96;--wm:url("data:image/png;base64,")}
.w-ares{aspect-ratio:512/96;--wm:url("data:image/png;base64,")}
.w-vandal{aspect-ratio:384/96;--wm:url("data:image/png;base64,")}
.w-bulldog{aspect-ratio:384/96;--wm:url("data:image/png;base64,")}
.w-phantom{aspect-ratio:384/96;--wm:url("data:image/png;base64,")}
.w-judge{aspect-ratio:384/96;--wm:url("data:image/png;base64,")}
.w-bucky{aspect-ratio:384/96;--wm:url("data:image/png;base64,")}
.w-frenzy{aspect-ratio:256/96;--wm:url("data:image/png;base64,")}
.w-classic{aspect-ratio:256/96;--wm:url("data:image/png;base64,")}
.w-bandit{aspect-ratio:256/140;--wm:url("data:image/png;base64,")}
.w-ghost{aspect-ratio:256/96;--wm:url("data:image/png;base64,")}
.w-sheriff{aspect-ratio:256/96;--wm:url("data:image/png;base64,")}
.w-shorty{aspect-ratio:256/96;--wm:url("data:image/png;base64,")}
.w-operator{aspect-ratio:512/96;--wm:url("data:image/png;base64,")}
.w-guardian{aspect-ratio:384/96;--wm:url("data:image/png;base64,")}
.w-outlaw{aspect-ratio:512/96;--wm:url("data:image/png;base64,")}
.w-marshal{aspect-ratio:512/96;--wm:url("data:image/png;base64,")}
.w-spectre{aspect-ratio:256/96;--wm:url("data:image/png;base64,")}
.w-stinger{aspect-ratio:256/96;--wm:url("data:image/png;base64,")}
.w-melee{aspect-ratio:256/96;--wm:url("data:image/png;base64,")}
`;  // CS2 radar overviews (Valve's own de_*_radar art, extracted from the game depot, downscaled to
  // 256px and flattened onto the same dark base the VALORANT layouts use so both titles look alike).
  const CS2_LAYOUTS = {ancient:"data:image/jpeg;base64,",anubis:"data:image/jpeg;base64,",dust2:"data:image/jpeg;base64,",edin:"data:image/jpeg;base64,",grail:"data:image/jpeg;base64,",inferno:"data:image/jpeg;base64,",jura:"data:image/jpeg;base64,",mirage:"data:image/jpeg;base64,",nuke:"data:image/jpeg;base64,",overpass:"data:image/jpeg;base64,",palais:"data:image/jpeg;base64,",train:"data:image/jpeg;base64,",vertigo:"data:image/jpeg;base64,"};

  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const now = () => Date.now();

  // ====================== config ======================
  const CK = '_vmm_cfg_v1';
  const DEF_CFG = {
    w: 620,                 // panel width in px (the map itself is square)
    pos: null,              // {x,y} panel position
    size: 30,               // player icon size in px
    mapOp: 0.9,             // background map opacity
    showNames: true, showWeapons: true, showHp: true, showShield: true, showUlt: true,
    showTrails: false, trailLen: 8,
    showDead: true,         // keep showing dead players (greyed) at their last known position
    dimStale: true, staleMs: 5000,
    orient: {},             // per map: {fx,fy,sw}
    s4AsIc: true,           // if S4 isn't learned yet, assume it uses the same ids as IC
    shieldSwap: false,      // swap 32/33 = light/heavy
    defuseRadius: 7,        // % of the map: a live defender inside this radius of the spike counts as "near"
    showDefusing: true,     // inferred defuse-in-progress badge (see DEF_SINCE)
    defuseTight: 4,         // % of the map: how close counts as standing ON the spike
    showUltUsed: true,      // keep a dimmed, struck-through bolt on anyone who has cast this round
    ultFx: true,            // agent-specific flourish on cast (Viper's green haze)
    mapOverride: '',        // used only when the feed sends no map name
    palette: 'valorant',    // side colours: green defenders / red attackers, like bet365's own widget
    useSXSY: true,          // treat SX/SY as a plant (behind the three gates); turn off if it ever false-positives again
    min: false, hidden: false,
  };
  const loadCfg = () => { try { return JSON.parse(localStorage.getItem(CK) || 'null') || {}; } catch (e) { return {}; } };
  const CFG = Object.assign({}, DEF_CFG, loadCfg());
  CFG.orient = Object.assign({}, CFG.orient || {});
  const saveCfg = () => { try { localStorage.setItem(CK, JSON.stringify(CFG)); } catch (e) {} };

  // ====================== learned id maps, shared with the HUD script ======================
  const AK = '_pv_am_v', WK = '_pv_wm_v', SK = '_vmm_s4ic_v1';
  const jget = (k) => { try { return JSON.parse(localStorage.getItem(k) || 'null') || {}; } catch (e) { return {}; } };
  const jset = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} };
  // The IC weapon-icon ids are a DIFFERENT set per title, so CS2 must not read or write VALORANT's
  // learned names. Agents only exist in VALORANT, so that store stays single.
  const WKEYS = { valorant: WK, cs2: '_vmm_wm_cs2' };
  let AGENTS = jget(AK), WEAPONS_BY = { valorant: jget(WK), cs2: jget('_vmm_wm_cs2') }, S4IC_BY = Object.assign({ valorant: {}, cs2: {} }, jget(SK));
  const SEED_WEAPONS = { 6: 'Odin', 7: 'Ares', 8: 'Vandal', 9: 'Bulldog', 10: 'Phantom', 11: 'Judge', 12: 'Bucky', 13: 'Frenzy', 14: 'Classic', 15: 'Ghost', 16: 'Sheriff', 17: 'Shorty', 18: 'Operator', 19: 'Guardian', 20: 'Marshal', 21: 'Spectre', 22: 'Stinger', 34: 'Outlaw', 35: 'Bandit' };
  for (const ic in SEED_WEAPONS) if (!(ic in WEAPONS_BY.valorant)) WEAPONS_BY.valorant[ic] = SEED_WEAPONS[ic];   // VALORANT only - CS2 ids mean other guns
  let mapsAt = 0;
  const refreshMaps = () => { if (now() - mapsAt < 3000) return; mapsAt = now(); AGENTS = Object.assign(jget(AK), AGENTS_OVR); const w = jget(WKEYS.valorant); for (const ic in SEED_WEAPONS) if (!(ic in w)) w[ic] = SEED_WEAPONS[ic]; WEAPONS_BY.valorant = w; WEAPONS_BY.cs2 = jget(WKEYS.cs2); };
  const AGENTS_OVR = {};   // labels set from this panel this session (these win over the stored ones)

  const AGENT_NAMES = ['Astra', 'Breach', 'Brimstone', 'Chamber', 'Clove', 'Cypher', 'Deadlock', 'Fade', 'Gekko', 'Harbor', 'Iso', 'Jett', 'KAY/O', 'Killjoy', 'Miks', 'Neon', 'Omen', 'Phoenix', 'Raze', 'Reyna', 'Sage', 'Skye', 'Sova', 'Tejo', 'Veto', 'Viper', 'Vyse', 'Waylay', 'Yoru'];
  const slug = n => String(n || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  // Both titles share one lookup; the map pools don't collide. CUSTOM sits on top: Riot ships maps
  // faster than this script gets rebuilt (Summit landed in June 2026), so a layout can be dropped in
  // at runtime with vm.layout('summit', dataUri) and it persists in localStorage.
  const CMK = '_vmm_maps_v1';
  Object.assign(MAP_LAYOUTS, CS2_LAYOUTS, jget(CMK));
  const mapSlug = name => { const n = slug(name); return MAP_LAYOUTS[n] ? n : null; };
  const weaponName = ic => (WEAPONS_BY[GAMEKEY] || {})[ic] || (ic ? 'ic#' + ic : '');
  const wSlug = name => {
    const n = slug(name); if (!n) return null;
    if (/knife|melee|blade|tactical/.test(n)) return 'melee';
    for (const k of ['classic', 'shorty', 'frenzy', 'ghost', 'sheriff', 'stinger', 'bucky', 'judge', 'bulldog', 'guardian', 'phantom', 'vandal', 'marshal', 'outlaw', 'ares', 'odin', 'bandit']) if (n.indexOf(k) >= 0) return k;
    if (/spectre|specter/.test(n)) return 'spectre';
    if (/operator|^op$/.test(n)) return 'operator';
    return null;
  };

  // ====================== CSP probe (bet365 may block data: images) ======================
  let DATA_OK = false;
  (function () {
    try { addEventListener('securitypolicyviolation', e => { const d = String(e.effectiveDirective || e.violatedDirective || ''); if (d.indexOf('img-src') >= 0 && String(e.blockedURI).indexOf('data') === 0) DATA_OK = false; }, { passive: true }); } catch (e) {}
    try { const t = new Image(); t.onload = () => { DATA_OK = true; paint(); }; t.src = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+M8AAAMFAX2wA4pFAAAAAElFTkSuQmCC'; } catch (e) {}
  })();

  // ====================== sides ======================
  // bet365 ships CS2 and VALORANT over the SAME zap product, so the record shape is shared and only
  // the field letters and a few constants differ. The map pools are disjoint, so the live map tells
  // us which title we're on - no setting to get wrong, it just switches.
  const GAMES = {
    valorant: {
      name: 'VALORANT', objDur: 45, defuseSecs: 7, atk: 'ATK', def: 'DEF', obj: 'SPIKE', glyph: '\u{1F53B}', pal: 'valorant', cur: '',
      f: { hp: 'HE', armor: 'S5', alive: 'S1', kills: 'D1', assists: 'D2', deaths: 'D3', money: 'PO', weapon: 'S4', ult: 'S2', ultMax: 'S3', agent: 'IG', carrier: 'SP', kit: null },
      armorMax: 50,   // 32 = light (25), 33 = heavy (50)
      maps: ['Ascent', 'Bind', 'Haven', 'Split', 'Icebox', 'Breeze', 'Fracture', 'Pearl', 'Lotus', 'Sunset', 'Abyss', 'Corrode', 'Summit'],
    },
    cs2: {
      name: 'CS2', objDur: 40, defuseSecs: 10, atk: 'T', def: 'CT', obj: 'BOMB', glyph: '\u{1F4A3}', pal: 'cs2', cur: '$',
      // field map from the HUD script's CS2 profile: hp=S2, armor=S6, weapon=S5, money=S4,
      // kit=S7 (defuse kit), bomb carrier=S8. No ults and no agents in CS2, so those stay null
      // and everything keyed off them (bolt, haze, portraits) switches itself off.
      f: { hp: 'S2', armor: 'S6', alive: 'S1', kills: 'D1', assists: 'D2', deaths: 'D3', money: 'S4', weapon: 'S5', ult: null, ultMax: null, agent: null, carrier: 'S8', kit: 'S7' },
      armorMax: 100,
      maps: ['Dust2', 'Dust 2', 'Mirage', 'Inferno', 'Nuke', 'Overpass', 'Ancient', 'Anubis', 'Vertigo', 'Train', 'Cache', 'Cobblestone'],
    },
  };
  let GAMEKEY = 'valorant', GAME = GAMES.valorant;
  const gameByMap = m => { const x = String(m || '').trim().toLowerCase(); for (const k in GAMES) if (GAMES[k].maps.some(n => n.toLowerCase() === x)) return k; return null; };
  const knownMap = m => !m || !!gameByMap(m);

  const ATK_RAW = new Set(['T', 'A', 'ATK', 'ATT', 'ATTACK', 'ATTACKING', 'ATTACKER', 'ATTACKERS']);
  const DEF_RAW = new Set(['CT', 'D', 'DEF', 'DEFENCE', 'DEFENSE', 'DEFENDING', 'DEFENDER', 'DEFENDERS']);
  const sideRole = raw => { const u = String(raw || '').toUpperCase(); return ATK_RAW.has(u) ? 'atk' : DEF_RAW.has(u) ? 'def' : null; };
  // Side colours. The blue/orange pair is CS2's CT/T convention, which is what this started from,
  // but VALORANT (and bet365's own match widget) reads green for Defenders and red for Attackers.
  // Default to that; the old pair stays available for anyone used to it.
  const PALETTES = {
    valorant: { def: '#3ec78a', atk: '#e2564f', name: 'VALORANT (green / red)' },
    cs2:      { def: '#4ea1f0', atk: '#f0b54e', name: 'CS2 (blue / orange)' },
    auto:     { def: '#3ec78a', atk: '#e2564f', name: 'Auto (per title)' },
  };
  const PAL = () => PALETTES[CFG.palette === 'auto' ? GAME.pal : CFG.palette] || PALETTES.valorant;
  const sideCol = raw => { const r = sideRole(raw), p = PAL(); return r === 'def' ? p.def : r === 'atk' ? p.atk : '#8b929c'; };

  // ====================== hook WebSocket (page + iframes) ======================
  const ERR = {};   // errors captured per phase - surfaced in the footer and in vm.diag()
  const STATS = { paintMs: 0, paintMax: 0, paints: 0, pruned: 0, slow: 0 };   // self-monitoring, read via vm.mem()
  const tappedWS = new WeakSet(), patchedWins = new WeakSet();
  const WSHOSTS = {};   // host -> {frames, recs, game} for diagnostics
  function patchWS(win) {
    try {
      if (!win || patchedWins.has(win) || !win.WebSocket) return; patchedWins.add(win);
      const proto = win.WebSocket.prototype, oAEL = proto.addEventListener;
      const tap = ws => {
        if (tappedWS.has(ws)) return; tappedWS.add(ws);
        let host = '?'; try { const u = new URL(ws.url); host = /sportspublisher/.test(u.pathname) ? 'sportspublisher' : u.host.split('.')[0]; } catch (e) {}
        WSHOSTS[host] = WSHOSTS[host] || { frames: 0, recs: 0, game: 0 };
        oAEL.call(ws, 'message', e => { if (typeof e.data === 'string') onFrame(e.data, host); });
      };
      win.WebSocket = new Proxy(win.WebSocket, { construct(T, a) { const ws = new T(...a); tap(ws); return ws; } });
      // safety net: a socket that already existed before we hooked is invisible to the
      // constructor Proxy. Intercepting addEventListener on the prototype catches any
      // socket that registers listeners later, including pre-existing ones.
      proto.addEventListener = function (t, fn, o) { try { if (t === 'message') tap(this); } catch (e) {} return oAEL.call(this, t, fn, o); };
      try {
        const d = Object.getOwnPropertyDescriptor(proto, 'onmessage');
        if (d && d.set) Object.defineProperty(proto, 'onmessage', { configurable: true, enumerable: d.enumerable, get: d.get, set(fn) { try { tap(this); } catch (e) {} return d.set.call(this, fn); } });
      } catch (e) {}
    } catch (e) { ERR.hook = String(e && e.message || e); }
  }
  patchWS(window);
  const sweep = () => { const f = document.getElementsByTagName('iframe'); for (let i = 0; i < f.length; i++) try { patchWS(f[i].contentWindow); } catch (e) {} };
  try { new MutationObserver(sweep).observe(document, { childList: true, subtree: true }); } catch (e) {}
  const ivp = setInterval(sweep, 300); setTimeout(() => clearInterval(ivp), 60000);

  // ====================== zap parser ======================
  const store = {}, RAW = [];
  let rawBytes = 0, added = 0;   // added = new topics since the last prune, so growth is tracked in O(1)
  let curE = null, CLS = '151', frames = 0, lastFrameT = 0;
  const merge = (t, s) => s.split(';').forEach(kv => { const i = kv.indexOf('='); if (i > 0) t[kv.slice(0, i)] = kv.slice(i + 1); });
  function reg(sub, fb) { if (!sub) return; const i = sub.indexOf(';'); const cls = i < 0 ? sub : sub.slice(0, i); const f = {}; if (i >= 0) merge(f, sub.slice(i + 1)); const it = f.IT || fb; if (it) { if (!store[it]) added++; store[it] = { cls, f }; } }
  const seenKills = new Set(), seenMarks = new Set();
  function parseRec(rec) {
    const s = rec.indexOf('\x01'); if (s < 0) return;
    const topic = rec.slice(0, s).replace(/^[\x14\x15]/, ''), rest = rec.slice(s + 1), type = rest[0], pay = rest.slice(2).replace(/\|$/, '');
    if (type === 'U') { if (!store[topic]) { store[topic] = { cls: '?', f: {} }; added++; } merge(store[topic].f, pay); }
    else if (type === 'F') pay.split('|').forEach(x => reg(x));
    else if (type === 'I') {
      const child = topic.split('/').pop(); reg(pay, child);
      if (curE && child.indexOf('GL' + curE + '-') === 0) {
        const f = (store[child] || {}).f || {}, evf = (store[`${curE}M${CLS}_1`] || {}).f || {};
        if (!knownMap(evf.D1)) return;
        const rnd = evf.CP || '?';
        if (f.S1 && f.S2) {                                   // ---- regular KILL ----
          const key = rnd + ':' + f.S2;
          if (!seenKills.has(key)) { seenKills.add(key); onKill({ killer: (f.S1 || '').split(',')[0], victim: f.S2, ic: +f.IC || 0 }); }
        } else if (f.S1 && !f.S2) {                           // ---- objective MARKER (TP=2 plant / TP=3 defuse) ----
          const key = rnd + ':' + f.TP + ':' + f.S1 + ':' + (f.TS || '');
          if (!seenMarks.has(key)) { seenMarks.add(key); onMarker(f, evf); }
        }
      }
    }
    else if (type === 'D') delete store[topic.split('/').pop()];
  }
  // bet365 pushes a topic for every market on the page, so the store only ever grew. Anything
  // not part of the current event (or an EV record, which eid() falls back on) gets dropped
  // periodically - otherwise a long session ends up carrying tens of thousands of dead entries.
  let pruneAt = 0;
  function pruneStore() {
    // triggered by VOLUME as well as by time: on a busy in-play page the store can gain thousands
    // of market topics in seconds, so waiting on a timer alone lets it balloon in between
    if (added < 2000 && now() - pruneAt < 30000) return;
    pruneAt = now(); added = 0;
    const E = curE; if (!E) return;
    const keys = Object.keys(store); if (keys.length < 1500) return;
    // "contains the event id" is far too loose - bet365's market topics carry it too. Keep only
    // the four shapes anything here actually reads (EV / TE / LS / GL) plus any EV-class record,
    // which eid() falls back on when the hash has no event in it. Everything else is dead weight.
    const keep = new RegExp('^(?:' + E + 'M\\d+_1$|TE' + E + '-|LS' + E + '-|GL' + E + ')');
    let n = 0;
    for (const k of keys) { if (!keep.test(k) && (store[k] || {}).cls !== 'EV') { delete store[k]; n++; } }
    if (n) STATS.pruned += n;
  }

  function onFrame(data, host) {
    frames++; lastFrameT = now();
    // keep a raw-frame ring for vm.raw(), but bounded by BYTES as well as count: zap frames run
    // to several KB each, so 4000 of them quietly held tens of MB, and that GC pressure shows up
    // as stutter once the tab has been open a while
    RAW.push({ h: host || '?', d: data, t: now() }); rawBytes += data.length;
    while (RAW.length > 400 || rawBytes > 4e6) { const g = RAW.shift(); if (!g) break; rawBytes -= g.d.length; }
    const recs = data.split('\x08');
    const H = WSHOSTS[host || '?'] || (WSHOSTS[host || '?'] = { frames: 0, recs: 0, game: 0 });
    H.frames++; H.recs += recs.length;
    // one record at a time: if ONE blows up the rest of the frame survives (a throw partway
    // through the old forEach left the store half-filled and the EV record never landed)
    for (const r of recs) {
      if (/M\d+_1\x01/.test(r) || r.indexOf('LS') === 0) H.game++;
      try { parseRec(r); } catch (e) { ERR.parse = String(e && e.message || e); }
    }
    pruneStore();
    try { sample(); } catch (e) { ERR.sample = String(e && e.stack || e).split('\n').slice(0, 2).join(' | '); }
    schedule();
  }

  // ====================== state reading ======================
  const F = () => GAME.f;
  // Player slots were hardcoded 0-4, which quietly loses anyone the feed puts elsewhere: a match
  // showed only 8 of 10 because two records sat outside that range. Don't assume - enumerate every
  // LS topic for the event and read the team/slot out of the topic name itself. The key list is
  // cached and only rebuilt when a new topic appears, so this stays cheap on a per-frame path.
  const LS_RE_CACHE = { E: '', added: -1, at: 0, keys: [] };
  function playerKeys(E) {
    if (E === LS_RE_CACHE.E && added === LS_RE_CACHE.added && now() - LS_RE_CACHE.at < 2000) return LS_RE_CACHE.keys;
    const re = new RegExp('^LS' + E + '-(\\d+)-(\\d+)_1_1$');
    const keys = [];
    for (const k in store) { const m = re.exec(k); if (m) keys.push({ k, team: +m[1], slot: +m[2] }); }
    keys.sort((a, b) => (a.team - b.team) || (a.slot - b.slot));
    LS_RE_CACHE.E = E; LS_RE_CACHE.added = added; LS_RE_CACHE.at = now(); LS_RE_CACHE.keys = keys;
    return keys;
  }
  const num = v => (v == null || v === '') ? null : (isNaN(+v) ? null : +v);
  function eid() {
    const m = (location.hash || '').match(/EV(\d+)C(\d+)/); if (m) { CLS = m[2]; return m[1]; }
    const e = Object.values(store).find(o => o.cls === 'EV' && (o.f.CL === CLS || o.f.CL === '151'));
    if (e) { if (e.f.CL) CLS = e.f.CL; return (String(e.f.IT).match(/^(\d+)M/) || [])[1]; }
    return null;
  }
  function readState() {
    const E = eid(); if (!E) return null; curE = E;
    const ev = store[`${E}M${CLS}_1`]; if (!ev) return null;
    // pick the title from the live map before reading any player field, since the field letters differ
    // bet365 sometimes sends no map name at all (D1 empty - the HUD shows "?" in that case).
    // A manual override fills the gap, but only when the feed genuinely has nothing, so it can
    // never mask a real name or leak into the next match.
    const mapName = ev.f.D1 || CFG.mapOverride || '';
    const g = gameByMap(mapName); if (g && g !== GAMEKEY) { GAMEKEY = g; GAME = GAMES[g]; }
    const FD = GAME.f;
    const teams = [1, 2].map(n => { const t = store[`TE${E}-${n}_1_1`]; if (!t) return null; const m = (t.f.SC || '').match(/(\d+)\((\d+)\)/); return { name: t.f.NA, side: t.f.D2, rounds: m ? +m[1] : 0 }; });
    const found = [];
    for (const e of playerKeys(E)) {
      const pl = store[e.k]; if (!pl) continue; const f = pl.f; if (!f.NA) continue;
      // rosters can carry extra records (coaches have shown up in this feed before), so score how
      // complete each one looks and keep the five most player-like per team rather than the first five
      const score = (f[FD.alive] != null ? 1 : 0) + (f[FD.hp] != null ? 1 : 0) + (FD.agent && f[FD.agent] ? 1 : 0) + (f.PX != null ? 1 : 0);
      found.push({
        team: e.team, slot: e.slot, score, side: (teams[e.team - 1] || {}).side, name: f.NA,
        hp: +f[FD.hp] || 0, shield: +f[FD.armor] || 0, alive: f[FD.alive] === '1',
        k: +f[FD.kills] || 0, a: +f[FD.assists] || 0, d: +f[FD.deaths] || 0,
        weapon: +f[FD.weapon] || 0, ult: FD.ult ? +f[FD.ult] || 0 : 0, ultMax: FD.ultMax ? +f[FD.ultMax] || 0 : 0,
        agent: FD.agent ? +f[FD.agent] || 0 : 0, spike: f[FD.carrier] === '1', kit: FD.kit ? f[FD.kit] === '1' : false,
        px: num(f.PX), py: num(f.PY), dx: num(f.DX), dy: num(f.DY),
      });
    }
    const players = [];
    [1, 2].forEach(tn => {
      const mine = found.filter(x => x.team === tn);
      if (mine.length > 5) mine.sort((a, b) => (b.score - a.score) || (a.slot - b.slot));
      players.push.apply(players, (mine.length > 5 ? mine.slice(0, 5) : mine).sort((a, b) => a.slot - b.slot));
    });
    return { E, ev: { ...ev.f }, map: mapName, mapFromFeed: !!ev.f.D1, round: +ev.f.CP || 0, live: ev.f.TT === '1', teams, players };
  }

  // ====================== positions (the feed pushes PX/PY per player, sporadically) ======================
  const POS = {};   // name -> {x,y,t,trail:[]}
  // Ult usage isn't a field in the feed, but it's derivable: S2 is the player's current ult points
  // and S3 the cost, so a player sitting at full who suddenly drops below it has just cast. Tracked
  // per round; a Set means a second cast in the same round (impossible anyway) can't double-count.
  const ULT_PREV = {}, ULT_USED = new Set(), ULT_AT = {};

  // The ult-used inference assumed S2 (ult points) drops from full when the ult is cast. Watched
  // live, it doesn't: a Viper ulted and the bolt stayed lit for the whole round, so S2 never moved.
  // Rather than guess at another field, record what DOES change on each player's record and let a
  // real match answer it. Noise fields (position, clock, hp, money) are excluded, the log is capped,
  // and sampling is throttled, so this is cheap enough to leave running.
  const FIELDLOG = [], FL_NOISE = new Set(['PX', 'PY', 'DX', 'DY', 'TU', 'TS', 'IT', 'ID', 'OR']);
  const RAWPREV = {};
  let flAt = 0;
  function logFields(E, st) {
    if (now() - flAt < 200) return; flAt = now();
    for (const e of playerKeys(E)) {
      const o = store[e.k]; if (!o || !o.f || !o.f.NA) continue;
      const f = o.f, nm = f.NA, prev = RAWPREV[nm];
      if (prev) {
        for (const k in f) {
          if (FL_NOISE.has(k) || f[k] === prev[k]) continue;
          FIELDLOG.push({ t: new Date().toLocaleTimeString([], { hour12: false }), round: st.round, player: nm, field: k, from: prev[k] === undefined ? '' : prev[k], to: f[k] });
        }
      }
      RAWPREV[nm] = Object.assign({}, f);
    }
    while (FIELDLOG.length > 600) FIELDLOG.shift();
  }
  // per-agent flourish when the ult goes off. Viper's is the one worth seeing at a glance, so her
  // icon takes on a green haze; the map is here so others can be added without touching the render.
  const ULT_FX = { viper: '#2fbf6a' };

  // "Defusing" is NOT in the feed - the only thing that ever arrives is the TP=3 marker once the
  // defuse has already completed. So this is an inference, and it is labelled as one everywhere it
  // shows up. Two things have to hold at once: a live defender is standing on the planted spike,
  // AND their position has stopped updating. Defusing pins you in place for 7s, so a defender who
  // goes still on top of the spike is the best evidence available. It can still be someone simply
  // holding the site, hence the question mark - it is a strong hint, not a fact.
  const DEF_SINCE = {};   // name -> timestamp they went still on the spike
  const defuseSecs = () => GAME.defuseSecs;   // 7s in VALORANT, 10s in CS2 (5s with a kit)
  function pushPos(name, x, y) {
    const p = POS[name] || (POS[name] = { trail: [] });
    if (p.x === x && p.y === y) { p.t = p.t || now(); return; }
    p.x = x; p.y = y; p.t = now();
    p.trail.push({ x, y, t: p.t }); if (p.trail.length > 24) p.trail.shift();
  }

  // ====================== objective: plant / defuse ======================
  const objDur = () => GAME.objDur;   // 45s spike / 40s bomb
  // Confidence level of whatever source declared the plant. A MORE reliable source can
  // correct (and undo) what a weaker one declared - previously the first plant won forever,
  // so one false positive blocked the real plant for the rest of the round.
  const CONF = { marker: 3, hist: 3, sxsy: 2, carrier: 1 };
  let OBJ = resetObj(), OBJLOG = [], KILLLOG = [], SXLOG = [];
  function resetObj(round) {
    return { round: round == null ? null : round, planted: false, at: 0, by: '', x: null, y: null, src: '', conf: 0, defused: false, defusedBy: '', boom: false, carrier: null, carrierPos: null, dropped: null, droppedAt: 0 };
  }
  function markPlant(who, src, xy, conf) {
    conf = conf || CONF.carrier;
    if (OBJ.planted && conf <= OBJ.conf) return;
    if (OBJ.planted) { OBJ.boom = false; OBJ.defused = false; OBJ.defusedBy = ''; }   // correction: the reliable source wins
    OBJ.planted = true; OBJ.at = now(); OBJ.by = who || ''; OBJ.conf = conf;
    const pos = xy || (who && POS[who] && POS[who].x != null ? { x: POS[who].x, y: POS[who].y } : null) || OBJ.carrierPos;
    if (pos) { OBJ.x = pos.x; OBJ.y = pos.y; }
    OBJ.src = src + (xy ? '' : pos ? (who && POS[who] ? ' - planter position' : ' - carrier last position') : ' - no position');
    flash('🔻 SPIKE PLANTED' + (who ? ' - ' + who : ''), PAL().atk);
    paint();
  }
  function markDefuse(who, src) {
    if (!OBJ.planted || OBJ.defused) return;
    OBJ.defused = true; OBJ.defusedBy = who || '';
    OBJ.src += ' - defuse: ' + src;
    for (const n in DEF_SINCE) delete DEF_SINCE[n];
    flash('✂ SPIKE DEFUSED' + (who ? ' - ' + who : ''), PAL().def);
    paint();
  }
  function onMarker(f, evf) {
    const tp = +f.TP || 0, side = String(f.D1 || '').toUpperCase(), who = f.S1, role = sideRole(side);
    OBJLOG.push({ t: new Date().toLocaleTimeString([], { hour12: false }), round: evf.CP, TP: f.TP, who, side, TS: f.TS, IG: f.IG, D3: f.D3, D4: f.D4, raw: { ...f } });
    if (OBJLOG.length > 120) OBJLOG.shift();
    // TP=3 confirmed against a real capture (S1=leaf, S2 empty, IC empty, D1=DEF, TS=5) = DEFUSE.
    // TP=2 is the other victimless marker the feed emits => plant. For an unknown TP, decide
    // by side instead: ATK => plant, DEF => defuse.
    if (tp === 3) markDefuse(who, 'TP=3 marker');
    else if (tp === 2) markPlant(who, 'TP=2 marker', null, CONF.marker);
    else if (role === 'def') markDefuse(who, 'TP=' + tp + ' marker, DEF side');
    else if (role === 'atk') markPlant(who, 'TP=' + tp + ' marker, ATK side', null, CONF.marker);
  }
  function onKill(k) {
    KILLLOG.push({ t: now(), ...k }); if (KILLLOG.length > 60) KILLLOG.shift();
    // learn S4 -> IC: the weapon the killer holds at that instant IS the one they killed with
    try {
      const st = LAST; if (!st) return;
      const p = st.players.find(x => x.name === k.killer);
      const M = S4IC_BY[GAMEKEY] || (S4IC_BY[GAMEKEY] = {});
      if (p && p.weapon && k.ic) { if (M[p.weapon] !== k.ic) { M[p.weapon] = k.ic; jset(SK, S4IC_BY); } }
    } catch (e) {}
    flash('☠ ' + k.killer + ' → ' + k.victim, '#c8ced8', 1200);
  }
  const s4Name = s4 => { if (!s4) return ''; const M = S4IC_BY[GAMEKEY] || {}, W = WEAPONS_BY[GAMEKEY] || {}; if (M[s4]) return weaponName(M[s4]); if (CFG.s4AsIc && W[s4]) return W[s4]; return ''; };
  const s4Sure = s4 => !!(s4 && (S4IC_BY[GAMEKEY] || {})[s4]);

  // ====================== per-frame sampling ======================
  let LAST = null, prevRound = null, prevLive = null, mapKey = '', prevHist = null, hadSX = false, liveAt = 0;
  const HOW_LETTER = { e: 'elim', E: 'elim', B: 'boom', w: 'defuse', t: 'time' };
  function sample() {
    const st = readState(); if (!st) return;
    const E = st.E;
    if (!knownMap(st.map)) return;
    LAST = st;
    // map change: round numbers restart, so the dedup sets must be cleared or map 2's
    // events get swallowed as duplicates of map 1's
    const mk2 = st.E + '|' + (st.map || '');
    if (mk2 !== mapKey) { mapKey = mk2; seenKills.clear(); seenMarks.clear(); for (const n in POS) delete POS[n]; clearMarks(); OBJ = resetObj(st.round); prevHist = null; hadSX = false; liveAt = 0; ULT_USED.clear(); for (const n in ULT_PREV) delete ULT_PREV[n]; }
    // round reset: on round number AND on the freezetime->live edge, because when CP doesn't
    // change (or changes late) the objective state used to bleed into the next round
    const wentLive = st.live && prevLive === false;
    if (st.round !== prevRound || wentLive) {
      OBJ = resetObj(st.round); hadSX = false; ULT_USED.clear();
      for (const n in POS) if (POS[n]) POS[n].trail.length = 0;
      prevRound = st.round;
    }
    if (wentLive) liveAt = now();
    if (!liveAt && st.live) liveAt = now();
    prevLive = st.live;
    // CORROBORATION LAYER: S2 on the match record is the round-by-round history
    // (digit = winning team, letter = how: e/E elim, B detonated, w defuse, t time).
    // When a new entry appears, its letter confirms how the round that just ended finished -
    // this works even when no TP marker arrives.
    const hist = String(st.ev.S2 || '');
    if (hist && hist !== prevHist) {
      const arr = hist.match(/\d[a-zA-Z]/g) || [], prevArr = (prevHist || '').match(/\d[a-zA-Z]/g) || [];
      if (arr.length > prevArr.length) {
        const how = HOW_LETTER[arr[arr.length - 1][1]];
        if (how === 'defuse') { if (!OBJ.planted) { OBJ.planted = true; OBJ.at = now() - objDur() * 1000; OBJ.src = 'S2 history'; } markDefuse(OBJ.defusedBy || '', 'S2 history'); }
        else if (how === 'boom' && !OBJ.boom) { OBJ.planted = true; OBJ.boom = true; flash('💥 SPIKE DETONATED', '#ff6b5a'); }
      }
      prevHist = hist;
    }
    // posiciones + carrier
    let carrier = null;
    st.players.forEach(p => {
      if (p.px != null || p.py != null) pushPos(p.name, p.px == null ? (POS[p.name] || {}).x : p.px, p.py == null ? (POS[p.name] || {}).y : p.py);
      else if (!p.alive && (p.dx != null || p.dy != null) && !POS[p.name]) pushPos(p.name, p.dx || 0, p.dy || 0);
      if (p.spike && sideRole(p.side) === 'atk' && p.alive) { if (!carrier || (POS[p.name] && POS[p.name].t > ((POS[carrier.name] || {}).t || 0))) carrier = p; }
    });
    try { logFields(E, st); } catch (e) { ERR.fieldlog = String(e && e.message || e); }
    st.players.forEach(p => {
      const q = ULT_PREV[p.name];
      if (q && p.ultMax > 0 && q.ultMax > 0 && q.ult >= q.ultMax && p.ult < q.ult) { ULT_USED.add(p.name); ULT_AT[p.name] = now(); }
      ULT_PREV[p.name] = { ult: p.ult, ultMax: p.ultMax };
    });
    if (carrier) {
      // somebody is holding it again, so the "dropped here" guess is stale - clearing this is what
      // was missing: the marker was set on the carrier's death and then never taken down, so it sat
      // there for the rest of the round even after the spike had been picked up and planted
      OBJ.carrier = carrier.name; OBJ.dropped = null; OBJ.droppedAt = 0;
      const q = POS[carrier.name]; if (q && q.x != null) OBJ.carrierPos = { x: q.x, y: q.y };
    } else if (OBJ.carrier && !OBJ.planted) {
      const c = st.players.find(p => p.name === OBJ.carrier);
      if (c && !c.alive && !OBJ.dropped) { OBJ.dropped = OBJ.carrierPos; OBJ.droppedAt = now(); }
    }
    if (OBJ.planted) { OBJ.dropped = null; }   // once it's down, where it fell is history
    // SX/SY: in the defuse capture these were CLEARED at round end, which is why I first read
    // them as the spike position. Confirmed false positive live: they stay set from the previous
    // round after the new one starts, declaring a plant at second 0 with all ten players alive.
    // They now only count when (a) they go from EMPTY to a value - not when already set, (b) the
    // round is live and (c) it has run >12s. And at medium confidence: a real TP=2 overrides them.
    const sxRaw = st.ev.SX, syRaw = st.ev.SY;
    const hasSX = sxRaw != null && sxRaw !== '' && syRaw != null && syRaw !== '' && !(+sxRaw === 0 && +syRaw === 0);
    if (hasSX !== hadSX) {
      SXLOG.push({ hora: new Date().toLocaleTimeString([], { hour12: false }), ronda: st.round, viva: st.live, SX: sxRaw, SY: syRaw, seg_de_ronda: liveAt ? ((now() - liveAt) / 1000).toFixed(1) : '—', plantado: OBJ.planted });
      if (SXLOG.length > 80) SXLOG.shift();
      if (hasSX && CFG.useSXSY && st.live && liveAt && now() - liveAt > 12000) markPlant(OBJ.carrier || '', 'SX/SY (transition)', { x: +sxRaw, y: +syRaw }, CONF.sxsy);
      hadSX = hasSX;
    }
    if (hasSX && OBJ.planted && OBJ.x == null) { OBJ.x = +sxRaw; OBJ.y = +syRaw; OBJ.src += ' → SX/SY'; }
    // defuse-in-progress inference (see DEF_SINCE above)
    if (OBJ.planted && !OBJ.defused && !OBJ.boom && OBJ.x != null) {
      st.players.forEach(p => {
        const q = POS[p.name];
        if (!p.alive || sideRole(p.side) !== 'def' || !q || q.x == null) { delete DEF_SINCE[p.name]; return; }
        const d = Math.hypot(sc(q.x) - sc(OBJ.x), sc(q.y) - sc(OBJ.y));
        const still = now() - q.t >= 1200;   // q.t is the last time their position actually CHANGED
        if (d <= CFG.defuseTight && still) { if (!DEF_SINCE[p.name]) DEF_SINCE[p.name] = q.t; }
        else delete DEF_SINCE[p.name];
      });
    } else for (const n in DEF_SINCE) delete DEF_SINCE[n];

    // detonation by timeout
    if (OBJ.planted && !OBJ.defused && !OBJ.boom && (now() - OBJ.at) / 1000 > objDur() + 1) { OBJ.boom = true; flash('💥 SPIKE DETONATED', '#ff6b5a'); }
  }
  const spikeLeft = () => OBJ.planted && !OBJ.defused && !OBJ.boom ? Math.max(0, Math.round(objDur() - (now() - OBJ.at) / 1000)) : null;

  // ====================== radar geometry ======================
  const sc = v => (v > 1.5 || v < -1.5) ? v : v * 100;
  function xy(rx, ry, slugKey) {
    const o = CFG.orient[slugKey || ''] || { fx: false, fy: false, sw: false };
    let x = sc(rx), y = sc(ry);
    if (o.sw) { const t = x; x = y; y = t; }
    if (o.fx) x = 100 - x;
    if (o.fy) y = 100 - y;
    return { x: clamp(x, 1, 99), y: clamp(y, 1, 99) };
  }

  // ====================== health colours ======================
  // >=70 green (paler as it drops) - 30-69 amber - <30 red
  function hpCol(hp) {
    hp = clamp(hp, 0, 100);
    if (hp >= 70) { const t = (hp - 70) / 30; return `hsl(145,${34 + 40 * t}%,${58 - 6 * t}%)`; }
    if (hp >= 30) { const t = (hp - 30) / 40; return `hsl(${34 + 12 * t},88%,55%)`; }
    return `hsl(${clamp(hp / 30 * 8, 0, 8)},82%,${48 + hp / 30 * 6}%)`;
  }
  // VALORANT sends a shield CODE (32 light / 33 heavy); CS2 sends armour as a plain 0-100 value.
  const shieldOf = p => {
    const v = p.shield; if (!v) return 0;
    if (GAMEKEY === 'cs2') return Math.min(100, v);
    const light = CFG.shieldSwap ? 33 : 32, heavy = CFG.shieldSwap ? 32 : 33;
    return v === light ? 25 : v === heavy ? 50 : (v > 0 && v <= 50 ? v : 25);
  };

  // ====================== agent auto-detection (read bet365's own portraits) ======================
  // The feed only carries IG, an opaque numeric agent id with no name attached, which is why every
  // portrait started out as initials. But bet365's own match widget DOES render agent art in the
  // page DOM, next to each player's name. So instead of hand-labelling ten ids per match, we scan
  // the document for images sitting near a live player's name, pull an agent slug out of the asset
  // URL (or alt/title text), and map that player's IG -> agent name automatically.
  // Matching is deliberately strict: the URL is split into alphanumeric tokens and a token must
  // EQUAL an agent slug, so a short name like "iso" can't match some unrelated path fragment.
  // Anything unrecognised is kept as a candidate for vm.scan(), never guessed at.
  // NOTE ON AGENT PORTRAITS
  // The feed only carries IG, an opaque numeric agent id with no name attached. I tried reading
  // the agent art straight out of bet365's page, but it turns out that art lives INSIDE the video
  // stream (video#matchLiveVideo) - it is burned into the pixels, not the DOM. So no amount of
  // scanning can recover it, and the scanner is gone rather than left in burning cycles.
  // Labelling is manual, in the Agents section of the settings panel. IG is stable across matches,
  // so it is a one-time job per agent and the labels are shared with the HUD script.

  // ====================== UI ======================
  const CSS = `
#vmmP{position:fixed;top:60px;right:14px;z-index:2147483646;background:#0d0f13;color:#dbe0e7;border:1px solid #262b33;border-radius:12px;
  font:12px/1.35 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;box-shadow:0 18px 54px #000c;user-select:none;overflow:hidden;display:flex;flex-direction:column}
#vmmP.hid{display:none}
#vmmH{display:flex;align-items:center;gap:8px;padding:7px 9px;background:linear-gradient(#191d24,#13161b);border-bottom:1px solid #23272f;cursor:grab}
#vmmH.drag{cursor:grabbing}
#vmmH .ttl{font-weight:700;letter-spacing:.3px;font-size:11px;color:#9fb0c4;text-transform:uppercase;white-space:nowrap}
#vmmH .sc{font-weight:800;font-size:13px;letter-spacing:.5px}
#vmmH .mp{color:#e7edf5;font-weight:600}
#vmmH .rd{color:#7c8899}
#vmmH .sp{flex:1}
.vbtn{background:#1c2029;border:1px solid #2b313b;color:#aab4c2;border-radius:6px;padding:2px 7px;cursor:pointer;font-size:11px;line-height:17px}
.vbtn:hover{background:#242a35;color:#e6ecf4}
.vbtn.on{background:#1d3550;border-color:#2f5f8f;color:#8fc6ff}
#vmmMap{position:relative;width:100%;aspect-ratio:1/1;background:#070809;overflow:hidden}
#vmmBg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none}
#vmmGrid{position:absolute;inset:0;pointer-events:none;background:
  linear-gradient(90deg,#ffffff08 1px,transparent 1px) 0 0/12.5% 12.5%,
  linear-gradient(#ffffff08 1px,transparent 1px) 0 0/12.5% 12.5%}
.pm{position:absolute;transform:translate(-50%,-50%);transition:left .4s linear,top .4s linear,opacity .3s;display:flex;flex-direction:column;align-items:center;gap:1px;pointer-events:auto;cursor:default}
.pm.dead{opacity:.34;filter:grayscale(.85)}
.pm.stale{opacity:.55}
.pmi{position:relative;width:var(--sz);height:var(--sz);border-radius:50%;overflow:visible;display:flex;align-items:center;justify-content:center}
.pmi .av{position:absolute;inset:0;border-radius:50%;background-size:cover;background-position:center top;background-color:#1b1f27;
  border:2px solid var(--col);box-shadow:0 0 0 1px #000a,0 2px 6px #000a;display:flex;align-items:center;justify-content:center;
  font-weight:800;font-size:calc(var(--sz)*.42);color:var(--col);overflow:hidden}
.pm.carr .av{box-shadow:0 0 0 2px #fff,0 0 10px #ffffff90}
.pm.def .av{}
.ultb{position:absolute;right:calc(var(--sz)*-.18);top:calc(var(--sz)*-.18);width:calc(var(--sz)*.46);height:calc(var(--sz)*.46);border-radius:50%;
  background:#2b1d00;border:1px solid #f5c542;color:#ffd75e;display:flex;align-items:center;justify-content:center;font-size:calc(var(--sz)*.3);
  box-shadow:0 0 8px #f5c54290;animation:vultp 1.6s ease-in-out infinite}
@keyframes vultp{0%,100%{box-shadow:0 0 4px #f5c54260}50%{box-shadow:0 0 12px #f5c542cc}}
.spkb{position:absolute;left:calc(var(--sz)*-.20);bottom:calc(var(--sz)*-.16);width:calc(var(--sz)*.46);height:calc(var(--sz)*.46);border-radius:50%;
  background:#3a1206;border:1px solid #ff7a4d;color:#ff9e78;display:none;align-items:center;justify-content:center;font-size:calc(var(--sz)*.26);
  line-height:1;box-shadow:0 0 8px #ff7a4d80;z-index:3}
.ultb.used{background:#141821;border-color:#3b4250;color:#6c7686;box-shadow:none;animation:none}
.ultb.used::after{content:'';position:absolute;left:6%;top:47%;width:88%;height:1.6px;background:#96a1b2;transform:rotate(-45deg);border-radius:2px}
.pm.ultfx .av{box-shadow:0 0 0 2px var(--fx),0 0 13px 2px var(--fx)}
.pm.ultfx .pmi::before{content:'';position:absolute;inset:-32%;border-radius:50%;pointer-events:none;z-index:0;opacity:.4;
  background:radial-gradient(circle,var(--fx) 0%,transparent 68%);animation:vmist 2.6s ease-in-out infinite}
@keyframes vmist{0%,100%{transform:scale(.9);opacity:.6}50%{transform:scale(1.14);opacity:1}}
.dfb{position:absolute;left:calc(var(--sz)*-.20);bottom:calc(var(--sz)*-.16);width:calc(var(--sz)*.46);height:calc(var(--sz)*.46);border-radius:50%;
  background:#062a2c;border:1px solid #43d6c4;color:#8ff0e2;display:none;align-items:center;justify-content:center;font-size:calc(var(--sz)*.24);
  line-height:1;box-shadow:0 0 8px #43d6c480;z-index:3;animation:vdef 1s ease-in-out infinite}
.dfb.late{border-color:#7dffa8;color:#c6ffd9;box-shadow:0 0 12px #7dffa8cc;animation-duration:.5s}
@keyframes vdef{0%,100%{transform:scale(.9)}50%{transform:scale(1.12)}}
.kitb{position:absolute;right:calc(var(--sz)*-.20);bottom:calc(var(--sz)*-.16);width:calc(var(--sz)*.44);height:calc(var(--sz)*.44);border-radius:50%;
  background:#0d2436;border:1px solid #5fa8d8;color:#bfe2f7;display:none;align-items:center;justify-content:center;font-size:calc(var(--sz)*.24);
  line-height:1;box-shadow:0 0 6px #5fa8d870;z-index:3}
#vmmSpike.busy .ic{filter:drop-shadow(0 0 8px #43d6c4)}
#vmmSpike.busy .rg{border-color:#43d6c4aa;animation-duration:.9s}
#vmmStat .dfz{color:#8ff0e2;font-weight:800}
.hpb{width:calc(var(--sz)*1.06);height:3px;background:#00000090;border:1px solid #00000060;border-radius:2px;overflow:hidden;margin-top:2px}
.hpb i{display:block;height:100%;transition:width .3s,background .3s}
.shb{width:calc(var(--sz)*1.06);height:2px;background:#00000080;border-radius:2px;overflow:hidden}
.shb i{display:block;height:100%;background:#63c8ff;box-shadow:0 0 4px #63c8ff80}
.pmw{height:calc(var(--sz)*.42);display:flex;align-items:center;justify-content:center;color:var(--col);margin-top:1px}
.pmw.unsure{opacity:.5}
.wico{display:inline-block;height:100%;width:auto}
.wmsk{background-color:currentColor;-webkit-mask-image:var(--wm);mask-image:var(--wm);-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:center;mask-position:center;-webkit-mask-size:contain;mask-size:contain;height:100%;aspect-ratio:var(--ar,3/1)}
.pmn{font-size:10px;font-weight:600;color:#e8eef6;text-shadow:0 1px 3px #000,0 0 6px #000;white-space:nowrap;max-width:96px;overflow:hidden;text-overflow:ellipsis}
.tr{position:absolute;width:3px;height:3px;border-radius:50%;transform:translate(-50%,-50%);pointer-events:none}
#vmmSpike{position:absolute;transform:translate(-50%,-50%);pointer-events:none;display:none;flex-direction:column;align-items:center;z-index:6}
#vmmSpike .ic{width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:19px;filter:drop-shadow(0 0 6px #ff5a3c);animation:vblink 1s steps(2,start) infinite}
#vmmSpike.def .ic{animation:none;filter:drop-shadow(0 0 6px var(--defcol,#3ec78a))}
#vmmSpike .rg{position:absolute;left:50%;top:12px;transform:translate(-50%,-50%);border:2px solid #ff5a3c80;border-radius:50%;width:26px;height:26px;animation:vring 1.4s ease-out infinite}
#vmmSpike.def .rg{display:none}
#vmmSpike .lb{font-size:10px;font-weight:800;color:#ffb4a4;text-shadow:0 1px 3px #000;white-space:nowrap}
@keyframes vblink{50%{opacity:.2}}
@keyframes vring{0%{width:16px;height:16px;opacity:.9}100%{width:56px;height:56px;opacity:0}}
#vmmFoot{display:flex;align-items:center;gap:8px;padding:5px 9px;border-top:1px solid #23272f;background:#101318;font-size:11px;color:#8793a4;flex-wrap:wrap}
#vmmStat{font-weight:700}
#vmmStat.plant{color:#ffb056}
#vmmStat.def{color:var(--defcol,#3ec78a)}
#vmmFlash{position:absolute;left:50%;top:8px;transform:translateX(-50%);background:#000000cc;border:1px solid #ffffff22;border-radius:20px;padding:3px 12px;font-weight:700;font-size:12px;opacity:0;transition:opacity .25s;pointer-events:none;z-index:9;white-space:nowrap}
#vmmGrip{position:absolute;right:0;bottom:0;width:18px;height:18px;cursor:nwse-resize;z-index:10;
  background:linear-gradient(135deg,transparent 46%,#4a5464 46%,#4a5464 54%,transparent 54%,transparent 66%,#4a5464 66%,#4a5464 74%,transparent 74%)}
#vmmSet{display:none;padding:8px 9px;border-top:1px solid #23272f;background:#0f1217;max-height:260px;overflow:auto}
#vmmSet.open{display:block}
#vmmSet .row{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:6px}
#vmmSet label{color:#8793a4;font-size:11px}
#vmmSet select,#vmmSet input[type=range]{background:#1a1e26;border:1px solid #2b313b;color:#cfd7e2;border-radius:5px;font-size:11px;padding:1px 3px}
#vmmSet .hd{color:#6f7a8a;text-transform:uppercase;font-size:10px;letter-spacing:.6px;margin:8px 0 4px}
.agr{display:flex;align-items:center;gap:6px;margin-bottom:4px}
.agr .who{color:#9fb0c4;font-size:11px;min-width:104px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.agp{width:26px;height:26px;flex:none;border-radius:5px;background:#1b1f27;background-size:cover;background-position:center top;
  display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#5f6b7c;border:1px solid #2b313b}
.dchip{background:#4a1112;border:1px solid #a3282b;color:#ff8f88;font-size:10px;font-weight:800;letter-spacing:1px;border-radius:4px;padding:1px 6px;cursor:pointer;display:none;animation:vdemo 1.4s ease-in-out infinite}
.dchip.on{display:inline-block}
@keyframes vdemo{50%{background:#6b191b;color:#ffc4bf}}
#vmmP.min #vmmMap,#vmmP.min #vmmFoot,#vmmP.min #vmmSet,#vmmP.min #vmmGrip{display:none}
`;

  let P, HDR, MAPEL, BG, SPK, FOOT, STAT, FLASH, SET, layer, gripEl;
  const marks = {};   // name -> element

  function build() {
    if (P) return;
    const st = document.createElement('style'); st.textContent = CSS + '\n' + AGENT_ICON_CSS.replace(/\.a-/g, '#vmmP .a-') + '\n' + WEAPON_ICON_CSS.replace(/\.w-/g, '#vmmP .w-');
    (document.head || document.documentElement).appendChild(st);

    P = document.createElement('div'); P.id = 'vmmP';
    P.innerHTML = `
      <div id="vmmH">
        <span class="ttl" id="vmmGame">MINIMAP</span>
        <span class="dchip" id="vmmDemo" title="Fake data. Click to leave demo mode.">DEMO</span>
        <span class="mp" id="vmmMapN">—</span>
        <span class="rd" id="vmmRd"></span>
        <span class="sc" id="vmmSc"></span>
        <span class="sp"></span>
        <button class="vbtn" id="vmmGear" title="Settings">⚙</button>
        <button class="vbtn" id="vmmMin" title="Minimize">–</button>
        <button class="vbtn" id="vmmX" title="Hide (Alt+M to bring back)">×</button>
      </div>
      <div id="vmmMap">
        <img id="vmmBg" alt="">
        <div id="vmmGrid"></div>
        <div id="vmmLayer" style="position:absolute;inset:0"></div>
        <div id="vmmSpike"><span class="rg"></span><span class="ic">🔻</span><span class="lb"></span></div>
        <div id="vmmFlash"></div>
      </div>
      <div id="vmmSet"></div>
      <div id="vmmFoot"><span id="vmmStat">esperando feed…</span><span class="sp" style="flex:1"></span><span id="vmmInfo"></span></div>
      <div id="vmmGrip"></div>`;
    (document.body || document.documentElement).appendChild(P);

    HDR = P.querySelector('#vmmH'); MAPEL = P.querySelector('#vmmMap'); BG = P.querySelector('#vmmBg');
    SPK = P.querySelector('#vmmSpike'); FOOT = P.querySelector('#vmmFoot'); STAT = P.querySelector('#vmmStat');
    FLASH = P.querySelector('#vmmFlash'); SET = P.querySelector('#vmmSet'); layer = P.querySelector('#vmmLayer'); gripEl = P.querySelector('#vmmGrip');

    P.style.width = CFG.w + 'px';
    if (CFG.pos) { P.style.left = CFG.pos.x + 'px'; P.style.top = CFG.pos.y + 'px'; P.style.right = 'auto'; }
    if (CFG.min) P.classList.add('min');
    if (CFG.hidden) P.classList.add('hid');

    // drag
    let dx = 0, dy = 0, dragging = false;
    HDR.addEventListener('mousedown', e => { if (e.target.closest('button')) return; dragging = true; HDR.classList.add('drag'); const r = P.getBoundingClientRect(); dx = e.clientX - r.left; dy = e.clientY - r.top; e.preventDefault(); });
    addEventListener('mousemove', e => {
      if (dragging) { const x = clamp(e.clientX - dx, 0, innerWidth - 80), y = clamp(e.clientY - dy, 0, innerHeight - 40); P.style.left = x + 'px'; P.style.top = y + 'px'; P.style.right = 'auto'; CFG.pos = { x, y }; }
      if (rz) { CFG.w = clamp(Math.round(rw + (e.clientX - rx)), 280, Math.min(1400, innerWidth - 20)); P.style.width = CFG.w + 'px'; }
    });
    addEventListener('mouseup', () => { if (dragging || rz) saveCfg(); dragging = false; rz = false; HDR.classList.remove('drag'); });
    // resize (the map is square, so width alone drives it)
    let rz = false, rx = 0, rw = 0;
    gripEl.addEventListener('mousedown', e => { rz = true; rx = e.clientX; rw = P.getBoundingClientRect().width; e.preventDefault(); });
    // wheel over the grip = fine width control
    P.querySelector('#vmmDemo').onclick = () => DEMO.stop();
    P.querySelector('#vmmGear').onclick = () => { SET.classList.toggle('open'); if (SET.classList.contains('open')) renderSet(); };
    P.querySelector('#vmmMin').onclick = () => { P.classList.toggle('min'); CFG.min = P.classList.contains('min'); saveCfg(); };
    P.querySelector('#vmmX').onclick = () => { P.classList.add('hid'); CFG.hidden = true; saveCfg(); };
    addEventListener('keydown', e => { if (e.altKey && (e.key === 'm' || e.key === 'M')) { P.classList.toggle('hid'); CFG.hidden = P.classList.contains('hid'); saveCfg(); } });
  }

  let flashT = 0;
  function flash(txt, col, ms) {
    if (!FLASH) return;
    FLASH.textContent = txt; FLASH.style.color = col || '#fff'; FLASH.style.opacity = '1';
    clearTimeout(flashT); flashT = setTimeout(() => { FLASH.style.opacity = '0'; }, ms || 2600);
  }

  // ---------- settings panel ----------
  function renderSet() {
    refreshMaps();
    const st = LAST, sl = st ? mapSlug(st.map) : null, o = CFG.orient[sl || ''] || { fx: false, fy: false, sw: false };
    const chk = (k, lbl) => `<button class="vbtn ${CFG[k] ? 'on' : ''}" data-t="${k}">${lbl}</button>`;
    // One row per PLAYER, not per agent id. Mirror picks are normal, and two players on opposite
    // teams holding the same agent share one IG - a Set collapsed them, so a ten-man roster showed
    // as eight rows and two players looked missing. The id is still what gets labelled, so a shared
    // one is noted on both rows and labelling either fills in both.
    const roster = st ? st.players.filter(p => p.agent) : [];
    const igCount = {}; roster.forEach(p => { (igCount[p.agent] = igCount[p.agent] || []).push(p.name); });
    SET.innerHTML = `
      <div class="row">${chk('showNames', 'Names')}${chk('showWeapons', 'Weapon')}${chk('showHp', 'Health')}${chk('showShield', 'Shield')}${chk('showUlt', 'Ult ⚡')}${chk('showUltUsed', 'Ult used')}${chk('ultFx', 'Viper haze')}${chk('showDefusing', 'Defusing?')}${chk('showTrails', 'Trails')}${chk('showDead', 'Dead')}${chk('dimStale', 'Dim stale pos')}</div>
      <div class="row"><label>Icon</label><input type="range" id="vmSz" min="16" max="60" value="${CFG.size}"><span id="vmSzV">${CFG.size}px</span>
        <label>Map</label><input type="range" id="vmOp" min="0" max="100" value="${Math.round(CFG.mapOp * 100)}"><span id="vmOpV">${Math.round(CFG.mapOp * 100)}%</span></div>
      <div class="hd">Orientation${sl ? ' - ' + esc(sl) : (st && st.map ? ' - no layout stored for ' + esc(st.map) : ' - no map name in the feed')}</div>
      ${st && !st.mapFromFeed ? `<div class="row"><label>${st.map ? 'Map set by hand' : 'Feed sent no map name - set it'}</label><select id="vmMapSel"><option value="">(none)</option>${Object.keys(GAMES).map(g => GAMES[g].maps.map(m => `<option ${slug(CFG.mapOverride) === slug(m) ? 'selected' : ''}>${m}</option>`).join('')).join('')}</select></div>` : ''}
      <div class="row">
        <button class="vbtn ${o.fx ? 'on' : ''}" data-o="fx">Flip X</button>
        <button class="vbtn ${o.fy ? 'on' : ''}" data-o="fy">Flip Y</button>
        <button class="vbtn ${o.sw ? 'on' : ''}" data-o="sw">Swap X/Y</button>
        <span style="color:#6f7a8a">saved per map</span>
      </div>
      <div class="hd">Side colours</div>
      <div class="row">${Object.keys(PALETTES).map(k => `<button class="vbtn ${(CFG.palette || 'valorant') === k ? 'on' : ''}" data-pal="${k}">${PALETTES[k].name}</button>`).join('')}</div>
      <div class="hd">Weapons / shield / spike</div>
      <div class="row">${chk('s4AsIc', 'S4 uses IC ids')}${chk('shieldSwap', 'Swap light/heavy')}${chk('useSXSY', 'Plant from SX/SY')}</div>
      <div class="hd">Agents (IG -> name, shared with the HUD)${roster.length ? ' · ' + roster.filter(p => AGENTS[p.agent]).length + '/' + roster.length + ' labelled' : ''}</div>
      ${roster.length ? roster.map(p => {
        const ig = p.agent, an = AGENTS[ig], asl = an && slug(an), hasArt = DATA_OK && asl && AGENT_ICON_SET.has(asl);
        const shared = (igCount[ig] || []).filter(n => n !== p.name);
        return `<div class="agr"><span class="agp${hasArt ? ' a-' + asl : ''}">${hasArt ? '' : '?'}</span>` +
          `<span class="who" title="${shared.length ? 'same agent id as ' + esc(shared.join(', ')) : ''}">${esc(p.name)} · IG ${ig}${shared.length ? ' ·↔' : ''}</span>` +
          `<select data-ig="${ig}"><option value="">(unlabelled)</option>${AGENT_NAMES.map(n => `<option ${slug(AGENTS[ig]) === slug(n) ? 'selected' : ''}>${n}</option>`).join('')}</select></div>`;
      }).join('') : (st ? (GAME.f.agent ? '<div style="color:#6f7a8a">no agent ids yet</div>' : '<div style="color:#6f7a8a">' + GAME.name + ' has no agents</div>') : '<div style="color:#6f7a8a">no live match</div>')}
      <div class="row" style="color:#6f7a8a;margin-top:4px">bet365 burns the agent art into the video stream, so it can't be read from the page. Label each IG once here - the id is stable, so portraits show automatically from then on, in this panel and in the HUD.</div>
      <div class="hd">Console</div>
      <div class="row" style="color:#6f7a8a">vm.explore() · vm.coords() · vm.dump() · vm.pos() · vm.diag()</div>`;
    SET.querySelectorAll('[data-t]').forEach(b => b.onclick = () => { const k = b.dataset.t; CFG[k] = !CFG[k]; saveCfg(); renderSet(); paint(true); });
    const msel = SET.querySelector('#vmMapSel');
    if (msel) msel.onchange = () => { CFG.mapOverride = msel.value; saveCfg(); try { sample(); } catch (e) {} renderSet(); paint(true); };
    SET.querySelectorAll('[data-pal]').forEach(b => b.onclick = () => { CFG.palette = b.dataset.pal; saveCfg(); renderSet(); paint(true); });
    SET.querySelectorAll('[data-o]').forEach(b => b.onclick = () => { const k = b.dataset.o, key = sl || ''; const cur = Object.assign({ fx: false, fy: false, sw: false }, CFG.orient[key] || {}); cur[k] = !cur[k]; CFG.orient[key] = cur; saveCfg(); renderSet(); paint(true); });
    SET.querySelectorAll('select[data-ig]').forEach(s => s.onchange = () => { const ig = s.dataset.ig, v = s.value; const store2 = jget(AK); if (v) { store2[ig] = v; AGENTS_OVR[ig] = v; } else { delete store2[ig]; delete AGENTS_OVR[ig]; } jset(AK, store2); AGENTS = Object.assign(store2, AGENTS_OVR); Object.keys(marks).forEach(n => { const av = marks[n].querySelector('.av'); if (av) av.removeAttribute('data-a'); }); paint(true); renderSet(); });
    const sz = SET.querySelector('#vmSz'), op = SET.querySelector('#vmOp');
    sz.oninput = () => { CFG.size = +sz.value; SET.querySelector('#vmSzV').textContent = CFG.size + 'px'; paint(true); };
    sz.onchange = saveCfg;
    op.oninput = () => { CFG.mapOp = +op.value / 100; SET.querySelector('#vmOpV').textContent = op.value + '%'; paint(true); };
    op.onchange = saveCfg;
  }

  // ====================== pintado ======================
  let raf = 0, lastPaint = 0;
  const schedule = () => { if (raf) return; raf = requestAnimationFrame(() => { raf = 0; if (now() - lastPaint > 90) paint(); }); };
  setInterval(() => paint(), 250);

  function paint(force) {
    build(); if (!P || P.classList.contains('hid')) return;
    const _t0 = now();
    lastPaint = _t0;
    refreshMaps();
    // demo must NEVER mask a real match: the moment a feed with a roster arrives, it switches itself off
    if (DEMO.on && LAST && LAST.players && LAST.players.length >= 6) {
      DEMO.stop();
      flash('demo off - live match: ' + (LAST.map || ''), '#8fe0a0', 3500);
    }
    const st = DEMO.on ? DEMO.state() : LAST;
    P.querySelector('#vmmDemo').classList.toggle('on', DEMO.on);
    P.style.setProperty('--defcol', PAL().def); P.style.setProperty('--atkcol', PAL().atk);
    MAPEL.style.setProperty('--sz', CFG.size + 'px');
    layer.style.setProperty('--sz', CFG.size + 'px');

    // cabecera
    const mapN = st ? (st.map || '—') : '—';
    P.querySelector('#vmmMapN').textContent = mapN;
    P.querySelector('#vmmGame').textContent = st ? GAME.name : 'MINIMAP';
    P.querySelector('#vmmRd').textContent = st && st.round ? 'R' + st.round : '';
    P.querySelector('#vmmSc').innerHTML = st && st.teams && st.teams[0] && st.teams[1]
      ? `<span style="color:${sideCol(st.teams[0].side)}">${esc(st.teams[0].name || '')} ${st.teams[0].rounds}</span> <span style="color:#5c6675">:</span> <span style="color:${sideCol(st.teams[1].side)}">${st.teams[1].rounds} ${esc(st.teams[1].name || '')}</span>` : '';

    // background
    const sl = st ? mapSlug(st.map) : null;
    if (sl && DATA_OK) { const src = MAP_LAYOUTS[sl]; if (BG.getAttribute('data-k') !== sl) { BG.src = src; BG.setAttribute('data-k', sl); } BG.style.display = ''; BG.style.opacity = CFG.mapOp; }
    else { BG.style.display = 'none'; }

    if (!st) {
      // diagnose instead of going quiet: say exactly WHICH step of the chain breaks
      const keys = Object.keys(store), E = eid();
      const evc = keys.filter(k => /M\d+_1$/.test(k)), lsc = keys.filter(k => k.indexOf('LS') === 0);
      let why;
      if (!frames) why = 'waiting for feed...';
      else if (!keys.length) why = `feed connected (${frames} frames) - parser stored nothing`;
      else if (!E) why = `${keys.length} records - can't resolve the event id (no EV in the hash, no EV record)`;
      else if (!store[`${E}M${CLS}_1`]) why = `event ${E} - missing record ${E}M${CLS}_1 (CLS=${CLS}, ${evc.length} candidates)`;
      else why = `event ${E} resolved - ${lsc.length} player records`;
      STAT.textContent = why + (ERR.sample ? ' - ERROR: ' + ERR.sample : ERR.parse ? ' - parse ERROR: ' + ERR.parse : '');
      STAT.className = '';
      P.querySelector('#vmmInfo').textContent = 'vm.diag()';
      clearMarks(); tock(_t0); return;
    }

    // ---- players ----
    const seen = new Set();
    st.players.forEach(p => {
      const q = POS[p.name] || (DEMO.on ? DEMO.pos[p.name] : null);
      const hasPos = q && q.x != null;
      if (!hasPos) return;
      if (!p.alive && !CFG.showDead) return;
      seen.add(p.name);
      const { x, y } = xy(q.x, q.y, sl);
      let el = marks[p.name];
      if (!el) {
        el = document.createElement('div'); el.className = 'pm';
        el.innerHTML = `<div class="pmi"><div class="av"></div><div class="ultb">⚡</div><div class="spkb"></div><div class="dfb">🔧</div><div class="kitb">🧰</div></div><div class="hpb"><i></i></div><div class="shb"><i></i></div><div class="pmw"></div><div class="pmn"></div>`;
        layer.appendChild(el); marks[p.name] = el;
      }
      const col = sideCol(p.side);
      el.style.setProperty('--col', col);
      el.style.left = x + '%'; el.style.top = y + '%';
      const stale = CFG.dimStale && q.t && (now() - q.t > CFG.staleMs);
      el.classList.toggle('dead', !p.alive);
      el.classList.toggle('stale', !!stale && p.alive);
      el.classList.toggle('carr', !!p.spike && !OBJ.planted);
      // portrait
      const av = el.querySelector('.av'), an = AGENTS[p.agent], asl = an && slug(an);
      const key = (DATA_OK && asl && AGENT_ICON_SET.has(asl)) ? asl : '';
      if (av.getAttribute('data-a') !== (key || 'txt:' + p.name)) {
        av.className = 'av' + (key ? ' a-' + key : '');
        av.textContent = key ? '' : (p.name || '?').replace(/[^A-Za-z0-9]/g, '').slice(0, 2).toUpperCase();
        av.setAttribute('data-a', key || 'txt:' + p.name);
      }
      av.title = `${p.name} · ${an || (p.agent ? 'IG ' + p.agent : '')} · ${p.alive ? p.hp + 'hp' : 'dead'} · ${p.k}/${p.d}/${p.a}${p.ultMax ? ' · ult ' + p.ult + '/' + p.ultMax : ''}${stale ? ' - pos ' + Math.round((now() - q.t) / 1000) + 's' : ''}`;
      // ult
      const ub = el.querySelector('.ultb'), ready = p.ultMax > 0 && p.ult >= p.ultMax, used = ULT_USED.has(p.name);
      ub.style.display = (CFG.showUlt && (ready || (used && CFG.showUltUsed))) ? 'flex' : 'none';
      ub.classList.toggle('used', !ready && used);
      ub.title = ready ? 'ult ready' : used ? 'ult used this round' : '';
      // objective carrier (spike / bomb), bottom-left, mirroring the ult badge in the opposite corner
      const sb = el.querySelector('.spkb');
      sb.style.display = (p.spike && !OBJ.planted && sideRole(p.side) === 'atk') ? 'flex' : 'none';
      if (sb.textContent !== GAME.glyph) sb.textContent = GAME.glyph;
      sb.title = 'carrying the ' + GAME.obj.toLowerCase();
      // defuse-in-progress badge, same corner as the carrier badge (a defender never carries it,
      // so the two can't collide). Elapsed time is shown against the 7s a defuse takes.
      const db = el.querySelector('.dfb'), dsince = DEF_SINCE[p.name];
      if (CFG.showDefusing && dsince) {
        const el2 = (now() - dsince) / 1000;
        db.style.display = 'flex';
        db.classList.toggle('late', el2 >= defuseSecs() * 0.5);
        db.title = 'possibly defusing - still on the ' + GAME.obj.toLowerCase() + ' for ' + el2.toFixed(1) + 's of ' + defuseSecs() + 's';
      } else db.style.display = 'none';
      const kb = el.querySelector('.kitb');
      kb.style.display = (p.kit && p.alive) ? 'flex' : 'none';   // CS2 defuse kit (S7); never set in VALORANT
      kb.title = 'defuse kit';
      // agent-specific ult flourish (Viper's green haze)
      const fx = (used && CFG.ultFx) ? ULT_FX[slug(AGENTS[p.agent])] : null;
      el.classList.toggle('ultfx', !!fx);
      if (fx) el.style.setProperty('--fx', fx);
      // health
      const hpb = el.querySelector('.hpb'); hpb.style.display = CFG.showHp && p.alive ? '' : 'none';
      if (p.alive) { const i = hpb.firstChild; i.style.width = clamp(p.hp, 0, 100) + '%'; i.style.background = hpCol(p.hp); }
      // shield
      const shb = el.querySelector('.shb'), sv = shieldOf(p);
      shb.style.display = (CFG.showShield && p.alive && sv > 0) ? '' : 'none';
      if (sv > 0) shb.firstChild.style.width = (sv / GAME.armorMax * 100) + '%';
      // weapon
      const wq = el.querySelector('.pmw');
      if (CFG.showWeapons && p.alive && p.weapon) {
        const nm = s4Name(p.weapon), ws = wSlug(nm);
        wq.style.display = '';
        wq.classList.toggle('unsure', !s4Sure(p.weapon));
        wq.title = nm || ('S4 #' + p.weapon);
        const k2 = (DATA_OK && ws && WEAPON_ICON_SET.has(ws)) ? 'm:' + ws : 't:' + (nm || p.weapon);
        if (wq.getAttribute('data-w') !== k2) {
          wq.setAttribute('data-w', k2);
          wq.innerHTML = (DATA_OK && ws && WEAPON_ICON_SET.has(ws))
            ? `<span class="wico wmsk w-${ws}"></span>`
            : `<span style="font-size:9px;font-weight:700;letter-spacing:.2px;text-shadow:0 1px 2px #000">${esc((nm || 'S4#' + p.weapon).slice(0, 9))}</span>`;
        }
      } else { wq.style.display = 'none'; }
      // name
      const nEl = el.querySelector('.pmn'); nEl.style.display = CFG.showNames ? '' : 'none';
      if (nEl.textContent !== p.name) nEl.textContent = p.name;
    });
    Object.keys(marks).forEach(n => { if (!seen.has(n)) { marks[n].remove(); delete marks[n]; } });

    // ---- trails ----
    layer.querySelectorAll('.tr').forEach(e => e.remove());
    if (CFG.showTrails) {
      st.players.forEach(p => {
        const q = POS[p.name]; if (!q || !q.trail.length || !p.alive) return;
        const t = q.trail.slice(-CFG.trailLen);
        t.forEach((pt, i) => {
          const c = xy(pt.x, pt.y, sl), d = document.createElement('div');
          d.className = 'tr'; d.style.left = c.x + '%'; d.style.top = c.y + '%';
          d.style.background = sideCol(p.side); d.style.opacity = (0.12 + 0.5 * (i / t.length)).toFixed(2);
          layer.appendChild(d);
        });
      });
    }

    // ---- spike ----
    const left = spikeLeft();
    if (OBJ.planted && OBJ.x != null) {
      const c = xy(OBJ.x, OBJ.y, sl);
      SPK.style.display = 'flex'; SPK.style.left = c.x + '%'; SPK.style.top = c.y + '%';
      SPK.classList.toggle('def', OBJ.defused);
      SPK.classList.toggle('busy', !OBJ.defused && !OBJ.boom && Object.keys(DEF_SINCE).length > 0);
      SPK.querySelector('.ic').textContent = OBJ.defused ? '✓' : OBJ.boom ? '💥' : GAME.glyph;
      SPK.querySelector('.lb').textContent = OBJ.defused ? 'DEFUSED' : OBJ.boom ? 'BOOM' : (left != null ? '0:' + String(left).padStart(2, '0') : '');
    } else if (!OBJ.planted && OBJ.dropped && CFG.showDead && now() - OBJ.droppedAt < 20000) {
      const c = xy(OBJ.dropped.x, OBJ.dropped.y, sl);
      SPK.style.display = 'flex'; SPK.style.left = c.x + '%'; SPK.style.top = c.y + '%';
      SPK.classList.add('def'); SPK.querySelector('.ic').textContent = GAME.glyph; SPK.querySelector('.lb').textContent = 'dropped?';
    } else { SPK.style.display = 'none'; SPK.querySelector('.lb').textContent = ''; }   // don't leave stale text inside a hidden marker

    // ---- status ----
    let txt = '', cls = '';
    if (OBJ.defused) { txt = '✂ defused' + (OBJ.defusedBy ? ' by ' + OBJ.defusedBy : ''); cls = 'def'; }
    else if (OBJ.boom) { txt = '💥 detonated'; cls = 'plant'; }
    else if (OBJ.planted) {
      txt = `${GAME.glyph} planted${OBJ.by ? ' by ' + OBJ.by : ''}${left != null ? ' - 0:' + String(left).padStart(2, '0') : ''}`;
      cls = 'plant';
      // who is standing on the spike? (live defender inside the radius) -> defuse candidate
      if (OBJ.x != null) {
        const busy = Object.keys(DEF_SINCE);
        if (busy.length) {
          const best = busy.map(n => ({ n, s: (now() - DEF_SINCE[n]) / 1000 })).sort((a, b) => b.s - a.s)[0];
          txt += ` - \u{1F527} DEFUSING? ${best.n} ${best.s.toFixed(1)}s/${defuseSecs()}s`;
        } else {
          const near = st.players.filter(p => p.alive && sideRole(p.side) === 'def' && POS[p.name] && POS[p.name].x != null &&
            Math.hypot(sc(POS[p.name].x) - sc(OBJ.x), sc(POS[p.name].y) - sc(OBJ.y)) <= CFG.defuseRadius).map(p => p.name);
          if (near.length) txt += ' - near: ' + near.join(', ');
        }
      }
    } else if (OBJ.carrier) txt = '🎒 ' + GAME.obj.toLowerCase() + ' carrier: ' + OBJ.carrier;
    else txt = st.live ? 'round live' : 'between rounds';
    STAT.textContent = txt; STAT.className = cls;

    const withPos = st.players.filter(p => POS[p.name] && POS[p.name].x != null).length;
    P.querySelector('#vmmInfo').textContent = `${withPos}/${st.players.length} with position - ${frames} frames${sl ? '' : (st.map ? ' - no layout stored for ' + mapN + ' (vm.layout)' : ' - no map name in feed (\u2699 to set it)')}${DATA_OK ? '' : ' - CSP blocks data:'}${OBJ.src ? ' - ' + OBJ.src : ''}`;
    tock(_t0);
  }
  // a paint should cost a millisecond or two; if it ever doesn't, say so, instead of just
  // getting slower and slower with no explanation
  function tock(t0) {
    const d = now() - t0; STATS.paints++; STATS.paintMs = d;
    // the opening paints are one-offs: building the panel, injecting a 450KB stylesheet, and
    // handing the browser a 250KB data-URI map. Those aren't a symptom of anything, so they are
    // recorded separately - the watchdog only tracks steady-state cost, which is what would grow.
    if (STATS.paints <= 3) { STATS.warmupMs = Math.max(STATS.warmupMs || 0, d); return; }
    if (d > STATS.paintMax) STATS.paintMax = d;
    if (d > 60) { STATS.slow++; if (STATS.slow % 20 === 1) console.warn('[vm] slow paint: ' + d + 'ms (run vm.mem())'); }
  }
  function clearMarks() { Object.keys(marks).forEach(n => { marks[n].remove(); delete marks[n]; }); }

  // ====================== demo mode (exercise the UI with no live match) ======================
  const DEMO = {
    on: false, pos: {}, t: 0, mapName: 'Ascent',
    players: null,
    start(mapName) {
      this.mapName = mapName || 'Ascent'; this.on = true;
      const names = ['aspas', 'Less', 'cauanzin', 'tuyz', 'saadhak', 'leaf', 'Zellsis', 'johnqt', 'N4RRATE', 'Boostio'];
      const ags = ['Jett', 'Raze', 'Omen', 'Sova', 'Killjoy', 'Chamber', 'Skye', 'Cypher', 'Viper', 'Breach'];
      // fake 9xx IG ids kept in memory only (NOT written to _pv_am_v) so the real portraits show
      ags.forEach((a, i) => { AGENTS_OVR[900 + i] = a; });
      this.players = names.map((n, i) => ({
        team: i < 5 ? 1 : 2, side: i < 5 ? 'ATK' : 'DEF', name: n, hp: 100, shield: i % 3 === 0 ? 33 : 32, alive: true,
        k: 0, a: 0, d: 0, weapon: [8, 10, 21, 18, 14][i % 5], ult: i % 4 === 0 ? 7 : 3, ultMax: 7, agent: 900 + i, spike: i === 0,
      }));
      names.forEach((n, i) => { this.pos[n] = { x: 0.2 + 0.6 * Math.random(), y: 0.2 + 0.6 * Math.random(), t: now(), trail: [] }; });
      clearInterval(this.iv); this.iv = setInterval(() => this.tick(), 400); paint(true);
      return 'demo ON - vm.demo(false) to leave';
    },
    stop() { this.on = false; clearInterval(this.iv); clearMarks(); paint(true); return 'demo OFF'; },
    tick() {
      this.t++;
      this.players.forEach(p => {
        const q = this.pos[p.name];
        q.x = clamp(q.x + (Math.random() - 0.5) * 0.05, 0.05, 0.95);
        q.y = clamp(q.y + (Math.random() - 0.5) * 0.05, 0.05, 0.95);
        q.t = now(); q.trail.push({ x: q.x, y: q.y, t: q.t }); if (q.trail.length > 24) q.trail.shift();
        if (p.alive && Math.random() < 0.02) p.hp = Math.max(1, p.hp - Math.floor(Math.random() * 45));
        if (p.alive && Math.random() < 0.01) { p.alive = false; p.hp = 0; }
      });
      if (this.t === 12) { const c = this.pos['aspas']; OBJ = resetObj(1); OBJ.carrier = 'aspas'; OBJ.carrierPos = { x: c.x, y: c.y }; markPlant('aspas', 'demo'); }
      if (this.t === 60) markDefuse('leaf', 'demo');
      if (this.t > 75) { this.t = 0; OBJ = resetObj(1); this.players.forEach(p => { p.alive = true; p.hp = 100; }); }
      paint();
    },
    state() {
      const P2 = this.players.map(p => { const q = this.pos[p.name]; return Object.assign({}, p, { px: q.x, py: q.y }); });
      P2.forEach(p => { POS[p.name] = this.pos[p.name]; });
      return { E: 'demo', ev: {}, map: this.mapName, round: 1, live: true, teams: [{ name: 'LOUD', side: 'ATK', rounds: 6 }, { name: 'C9', side: 'DEF', rounds: 8 }], players: P2 };
    },
  };

  // ====================== console API ======================
  const api = {
    cfg: () => CFG,
    pos: () => { const st = LAST; if (!st) return console.warn('[vm] no live match'); const o = {}; st.players.forEach(p => { const q = POS[p.name] || {}; o[p.name] = { PX: p.px, PY: p.py, DX: p.dx, DY: p.dy, SP: p.spike, storedX: q.x, storedY: q.y, age_s: q.t ? ((now() - q.t) / 1000).toFixed(1) : '-', hp: p.hp, S5: p.shield, S4: p.weapon, ult: p.ult + '/' + p.ultMax, IG: p.agent }; }); console.table(o); return o; },
    obj: () => { console.table(OBJLOG.map(o => ({ time: o.t, round: o.round, TP: o.TP, who: o.who, side: o.side, TS: o.TS, IG: o.IG, D3: o.D3, D4: o.D4 }))); console.log('%cTP=3 = defuse (confirmed against a capture). If a different TP shows up right at the plant, tell me which and I will pin it.', 'color:#09c;font-weight:bold'); return OBJLOG; },
    fields: () => { const E = curE; if (!E) return console.warn('[vm] no live match'); const f = (store[`${E}M${CLS}_1`] || {}).f || {}; console.log('%c[vm] match record - watch SX/SY (spike position), VC, ET, S2 (round history)', 'color:#09c;font-weight:bold'); console.table(f); return f; },
    hist: () => { const E = curE, f = (store[`${E}M${CLS}_1`] || {}).f || {}; const h = String(f.S2 || ''); const HOW = { e: 'elimination', E: 'elimination', B: 'spike detonated', w: 'defuse', t: 'time' }; const rows = (h.match(/\d[a-zA-Z]/g) || []).map((x, i) => ({ round: i + 1, winner: 'team ' + x[0], code: x[1], how: HOW[x[1]] || '?' })); console.table(rows); return rows; },
    spike: () => OBJ,
    calib: () => { const st = LAST, sl = st ? mapSlug(st.map) : null; console.log('[vm] map=' + (st ? st.map : '-') + ' slug=' + sl + ' orientation=', CFG.orient[sl || '']); console.log('%cAdjust with the ⚙ Flip X / Flip Y / Swap buttons until positions line up; saved per map.', 'color:#09c'); return CFG.orient; },
    demo: v => (v === false ? DEMO.stop() : DEMO.start(typeof v === 'string' ? v : null)),
    agent: (ig, name) => { const s2 = jget(AK); if (name) { s2[ig] = name; AGENTS_OVR[ig] = name; } else { delete s2[ig]; delete AGENTS_OVR[ig]; } jset(AK, s2); AGENTS = Object.assign(s2, AGENTS_OVR); paint(true); return AGENTS; },
    diag: () => {
      const keys = Object.keys(store), E = eid();
      const byCls = {}; keys.forEach(k => { const c = (store[k] || {}).cls || '?'; (byCls[c] = byCls[c] || []).push(k); });
      const out = {
        hash: location.hash || '(empty)', hashMatch: !!(location.hash || '').match(/EV(\d+)C(\d+)/),
        CLS, eventResolved: E || '(none)', expectedTopic: E ? `${E}M${CLS}_1` : '-',
        topicExists: !!(E && store[`${E}M${CLS}_1`]),
        frames, recordsInStore: keys.length, socketsHooked: Object.keys(WSHOSTS).length,
        LAST: !!LAST, players: LAST ? LAST.players.length : 0, map: LAST ? LAST.map : '-',
      };
      console.log('%c[vm] diagnostics', 'color:#4ea1f0;font-weight:bold'); console.table(out);
      console.log('%csockets:', 'color:#09c;font-weight:bold'); console.table(WSHOSTS);
      console.log('%cclasses in the store (look for EV / TE / LS / MA):', 'color:#09c;font-weight:bold');
      const cls = {}; Object.keys(byCls).sort().forEach(c => cls[c] = { n: byCls[c].length, sample: byCls[c][0] }); console.table(cls);
      const evLike = keys.filter(k => /M\d+_1$/.test(k));
      console.log('%ctopics shaped {event}M{cls}_1 seen:', 'color:#09c;font-weight:bold', evLike.length ? evLike : '(none - the match feed is not reaching THIS script)');
      if (Object.keys(ERR).length) console.log('%cCaptured ERRORS:', 'color:#f55;font-weight:bold', ERR);
      console.log('%clast raw records:', 'color:#09c'); RAW.slice(-1).forEach(r => console.log(r.h, r.d.split('\x08').slice(0, 3)));
      return out;
    },
    sxsy: () => { console.table(SXLOG); console.log('%cEach row is an empty<->value change of SX/SY. If they only appear right at a real plant, they are the spike and I raise their confidence. If they fire at random or between rounds, I drop them entirely.', 'color:#09c;font-weight:bold'); return SXLOG; },
    // What actually moved on the player records, newest last. Run it right after seeing an ult on
    // stream: whatever field flipped at that moment is the one to wire up.
    fieldlog: (who) => {
      const rows = FIELDLOG.filter(r => !who || r.player.toLowerCase().indexOf(String(who).toLowerCase()) >= 0);
      if (!rows.length) return console.warn('[vm] nothing recorded yet - it needs a live round to watch');
      console.log('%c[vm] field changes on player records' + (who ? ' for ' + who : '') + ' - ' + rows.length + ' entries', 'color:#4ea1f0;font-weight:bold');
      console.table(rows.slice(-60));
      const byField = {}; rows.forEach(r => { byField[r.field] = (byField[r.field] || 0) + 1; });
      console.log('%chow often each field changed:', 'color:#09c'); console.table(byField);
      return rows;
    },
    // just the ult fields, current values plus every change seen this session
    ults: () => {
      const st = LAST; if (!st) return console.warn('[vm] no live match');
      const F = GAME.f;
      if (!F.ult) return console.warn('[vm] ' + GAME.name + ' has no ult fields');
      const cur = {}; st.players.forEach(p => { cur[p.name] = { points: p.ult, cost: p.ultMax, ready: p.ult >= p.ultMax && p.ultMax > 0, flaggedUsed: ULT_USED.has(p.name) }; });
      console.log('%c[vm] ult fields right now (' + F.ult + ' = points, ' + F.ultMax + ' = cost)', 'color:#4ea1f0;font-weight:bold');
      console.table(cur);
      const moves = FIELDLOG.filter(r => r.field === F.ult || r.field === F.ultMax);
      console.log('%cchanges to those fields so far: ' + moves.length, 'color:#09c');
      if (moves.length) console.table(moves.slice(-40));
      else console.log('%cnone at all - which is the thing to report: if the points never move, an ult cast is not visible in this feed and the badge cannot work off it.', 'color:#f90');
      return { cur, moves };
    },
    // Title-agnostic explorer. The parser stores every record whatever the game is, so this works
    // for a title the display doesn't support yet (LoL, Dota, whatever) - it just dumps what the
    // feed is actually carrying, with no assumptions about which letters mean what.
    // Name the map by hand when the feed doesn't. Only takes effect while D1 is empty.
    map: (name) => {
      CFG.mapOverride = name || ''; saveCfg();
      const sl = name ? mapSlug(name) : null;
      console.log('%c[vm] map override ' + (name ? 'set to "' + name + '"' + (sl ? ' (layout available)' : ' (no layout stored - see vm.layout)') : 'cleared'), 'color:#4ea1f0;font-weight:bold');
      // the map name is resolved while parsing, so re-read state rather than waiting for the next frame
      try { sample(); } catch (e) {}
      paint(true); return CFG.mapOverride;
    },
    // Store a layout image for a map at runtime. Pass a data: URI (or any URL the page may load).
    // Persists, survives updates to this script, and shows up like any built-in layout.
    layout: (name, uri) => {
      const k = slug(name);
      if (!k) return console.warn('[vm] usage: vm.layout("summit", "data:image/jpeg;base64,...")');
      const store2 = jget(CMK);
      if (!uri) { delete store2[k]; delete MAP_LAYOUTS[k]; jset(CMK, store2); console.log('[vm] layout for ' + k + ' removed'); paint(true); return; }
      if (!/^(data:image\/|https?:)/.test(uri)) return console.warn('[vm] that does not look like an image data: URI or URL');
      store2[k] = uri; jset(CMK, store2); MAP_LAYOUTS[k] = uri;
      console.log('%c[vm] layout stored for "' + k + '" (' + Math.round(uri.length / 1024) + ' KB). It will show whenever that map is live.', 'color:#4ea1f0;font-weight:bold');
      paint(true); return Object.keys(store2);
    },
    maps: () => {
      const custom = jget(CMK);
      const rows = {};
      Object.keys(GAMES).forEach(g => GAMES[g].maps.forEach(m => { const k = slug(m); if (!rows[k]) rows[k] = { title: GAMES[g].name, layout: MAP_LAYOUTS[k] ? (custom[k] ? 'custom' : 'built in') : 'MISSING' }; }));
      console.log('%c[vm] known maps and whether a layout is stored', 'color:#4ea1f0;font-weight:bold');
      console.table(rows); return rows;
    },
    explore: () => {
      const E = curE; if (!E) return console.warn('[vm] no event resolved yet - open a match first');
      const groups = {};
      for (const k in store) {
        if (k.indexOf(E) < 0) continue;
        const g = (k.match(/^([A-Za-z]+)/) || [0, '?'])[1];
        (groups[g] = groups[g] || []).push(k);
      }
      const summary = {};
      Object.keys(groups).sort().forEach(g => {
        const f = (store[groups[g][0]] || {}).f || {};
        summary[g] = { topics: groups[g].length, sample: groups[g][0], fields: Object.keys(f).join(' ') };
      });
      console.log('%c[vm] every topic family for event ' + E + ' (CLS=' + CLS + ')', 'color:#4ea1f0;font-weight:bold');
      console.table(summary);
      console.log('%cthen: vm.dump("LS") for the raw fields of a family, vm.coords() to hunt for positions', 'color:#09c');
      return summary;
    },
    // raw field table for every topic matching a prefix or substring - no curation, no field map
    dump: (match) => {
      const E = curE; if (!E) return console.warn('[vm] no event resolved yet');
      const out = {}; let n = 0;
      for (const k in store) {
        if (k.indexOf(E) < 0) continue;
        if (match && k.indexOf(match) < 0) continue;
        out[k] = Object.assign({}, (store[k] || {}).f); n++;
        if (n >= 40) break;
      }
      if (!n) return console.warn('[vm] nothing matching "' + match + '" - try vm.explore() first');
      console.log('%c[vm] raw fields, ' + n + ' topics' + (match ? ' matching "' + match + '"' : ''), 'color:#4ea1f0;font-weight:bold');
      console.table(out); return out;
    },
    // Hunt for coordinates without knowing the field names: anything numeric that looks like a
    // normalised 0-1 value or a 0-100 one, reported per topic so pairs stand out side by side.
    coords: () => {
      const E = curE; if (!E) return console.warn('[vm] no event resolved yet');
      const hits = {};
      for (const k in store) {
        if (k.indexOf(E) < 0) continue;
        const f = (store[k] || {}).f || {}, found = {};
        for (const key in f) {
          const v = f[key]; if (v === '' || v == null || isNaN(+v)) continue;
          const n = +v;
          if ((n > 0 && n < 1) || (n >= 0 && n <= 100 && String(v).indexOf('.') >= 0)) found[key] = v;
        }
        if (Object.keys(found).length) hits[k + (f.NA ? '  (' + f.NA + ')' : '')] = found;
      }
      const n = Object.keys(hits).length;
      if (!n) { console.log('%c[vm] no coordinate-looking fields anywhere in this event. If this is a live match, the feed most likely is not carrying positions for this title at all.', 'color:#f90;font-weight:bold'); return {}; }
      console.log('%c[vm] fields that look like coordinates (' + n + ' topics). Two that move together on a player record are your X/Y.', 'color:#4ea1f0;font-weight:bold');
      console.table(hits); return hits;
    },
    slots: () => {
      const E = curE; if (!E) return console.warn('[vm] no live match');
      const out = {};
      for (const k in store) { if (k.indexOf('LS' + E + '-') !== 0) continue; out[k] = Object.assign({}, (store[k] || {}).f); }
      console.log('%c[vm] every player record for this event, raw - which slots the feed uses and every field on them', 'color:#09c;font-weight:bold');
      console.table(out); return out;
    },
    mem: () => {
      const out = {
        storeTopics: Object.keys(store).length, prunedTotal: STATS.pruned,
        rawFrames: RAW.length, rawKB: Math.round(rawBytes / 1024),
        markers: Object.keys(marks).length, tracked: Object.keys(POS).length,
        objLog: OBJLOG.length, sxLog: SXLOG.length, killLog: KILLLOG.length,
        lastPaintMs: STATS.paintMs, worstPaintMs: STATS.paintMax, warmupPaintMs: STATS.warmupMs, paints: STATS.paints, slowPaints: STATS.slow,
        framesSeen: frames, socketsHooked: Object.keys(WSHOSTS).length,
      };
      console.log('%c[vm] memory / cost', 'color:#4ea1f0;font-weight:bold'); console.table(out);
      if (STATS.paintMax > 60) console.log('%cworst paint was ' + STATS.paintMax + 'ms - if that keeps climbing, paste this table to me.', 'color:#f90');
      return out;
    },
    err: () => ERR,
    raw: sub => { const o = RAW.flatMap(r => r.d.split('\x08')).filter(r => !sub || r.indexOf(sub) >= 0); console.log(o.length + ' records'); return o.join('\n'); },
    show: () => { P.classList.remove('hid'); CFG.hidden = false; saveCfg(); },
    reset: () => { localStorage.removeItem(CK); location.reload(); },
  };
  window.vm = api; window.__vmm = api;

  // boot
  const boot = () => { build(); paint(); };
  if (document.body) boot(); else addEventListener('DOMContentLoaded', boot);
  setTimeout(boot, 1500);
  console.log('%c[vm] VALORANT minimap loaded - vm.demo() to try it, Alt+M to hide/show', 'color:#4ea1f0;font-weight:bold');
})();
